using System.Net;using System.Net.Http;using System.Text;using System.Text.Json;using TownOfHost;
partial class Program {
const string PrivateMarker="DO-NOT-EMIT-PRIVATE-OAUTH-DATA";
sealed class OAuthReply:HttpMessageHandler {
 internal Func<CancellationToken,Task<HttpResponseMessage>> Response;internal int Calls;internal OAuthReply(int status,string body){Response=_=>Task.FromResult(new HttpResponseMessage((HttpStatusCode)status){Content=new StringContent(body,Encoding.UTF8,"application/json")});}
 protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken c){Calls++;Check(r.RequestUri.AbsoluteUri=="https://oauth2.googleapis.com/token");return Response(c);}
}
static Dictionary<string,string> CodeForm()=>new(){["client_id"]=Id,["grant_type"]="authorization_code",["code"]=PrivateMarker,["code_verifier"]=PrivateMarker,["redirect_uri"]="http://127.0.0.1:12345/oauth2/callback"};
static string TokenJson(string scope=null,string refresh="synthetic-refresh-private",string type="Bearer",int expires=3600,string access="synthetic-access-private")=>JsonSerializer.Serialize(new{access_token=access,refresh_token=refresh,scope=scope??YouTubePkceSession.Scope,token_type=type,expires_in=expires});
static async Task<YouTubeApiException> OAuthDenied(YouTubeDesktopOAuth e,Dictionary<string,string> form=null,CancellationToken token=default){try{await e.ExchangeAsync(form??CodeForm(),token);throw new Exception("Expected OAuth error");}catch(YouTubeApiException error){Check(error.OAuth!=null);Check(!(error.ToString()+error.OAuth.SafeLog+error.OAuth.UserMessage).Contains(PrivateMarker));return error;}}
static async Task DiagnosticTests(){
foreach(var (error,expected) in new[]{("invalid_client",YouTubeOAuthCode.InvalidClient),("invalid_request",YouTubeOAuthCode.InvalidRequest),("invalid_grant",YouTubeOAuthCode.InvalidGrant),("unauthorized_client",YouTubeOAuthCode.UnauthorizedClient),("access_denied",YouTubeOAuthCode.AccessDenied),("invalid_scope",YouTubeOAuthCode.InvalidScope),("redirect_uri_mismatch",YouTubeOAuthCode.RedirectMismatch),("admin_policy_enforced",YouTubeOAuthCode.PolicyBlocked),("org_internal",YouTubeOAuthCode.PolicyBlocked)})await Test("OAuth whitelisted failure "+error,async()=>{var h=new OAuthReply(400,JsonSerializer.Serialize(new{error,error_description=PrivateMarker,access_token=PrivateMarker,client_id=Id}));using var e=new YouTubeDesktopOAuth(new HttpClient(h));var failure=await OAuthDenied(e);Check(failure.OAuth.Stage==YouTubeOAuthStage.TokenExchange&&failure.OAuth.Code==expected&&failure.OAuth.HttpStatus==400&&h.Calls==1);});
foreach(var status in new[]{429,503})await Test("OAuth HTTP failure "+status,async()=>{using var e=new YouTubeDesktopOAuth(new HttpClient(new OAuthReply(status,"{}")));var failure=await OAuthDenied(e);Check(failure.OAuth.Code==(status==429?YouTubeOAuthCode.RateLimited:YouTubeOAuthCode.ServerError));Check(failure.Reason==(status==429?YouTubeFailure.QuotaExceeded:YouTubeFailure.NetworkInterrupted));});
foreach(var body in new[]{JsonSerializer.Serialize(new{error=PrivateMarker,error_description=PrivateMarker}),"not-json-"+PrivateMarker,"[\""+PrivateMarker+"\"]"})await Test("untrusted OAuth error body is never emitted "+body.Length,async()=>{using var e=new YouTubeDesktopOAuth(new HttpClient(new OAuthReply(400,body)));var failure=await OAuthDenied(e);Check(failure.OAuth.Code==YouTubeOAuthCode.OtherGoogleError);Check(!failure.OAuth.SafeLog.Contains(Id));});
await Test("OAuth success traces HTTP and validation without secrets",async()=>{var events=new List<YouTubeOAuthDiagnostic>();using var e=new YouTubeDesktopOAuth(new HttpClient(new OAuthReply(200,TokenJson())),events.Add);var result=await e.ExchangeAsync(CodeForm(),default);Check(result.Access.Valid&&result.RefreshToken.Length>0);Check(events.Any(x=>x.Stage==YouTubeOAuthStage.TokenExchange&&x.HttpStatus==200)&&events.Any(x=>x.Stage==YouTubeOAuthStage.TokenValidation));Check(events.All(x=>!x.SafeLog.Contains(Id)&&!x.SafeLog.Contains(PrivateMarker)&&!x.SafeLog.Contains("synthetic")));});
await Test("strict readonly scope mismatch has its own cause",async()=>{using var e=new YouTubeDesktopOAuth(new HttpClient(new OAuthReply(200,TokenJson(scope:"broader-scope-"+PrivateMarker))));var failure=await OAuthDenied(e);Check(failure.OAuth.Code==YouTubeOAuthCode.ScopeMismatch&&failure.OAuth.Stage==YouTubeOAuthStage.TokenValidation);});
foreach(var body in new[]{"not-json-"+PrivateMarker,"[]",TokenJson(type:"invalid"),TokenJson(expires:0),TokenJson(access:"")})await Test("invalid token response has a fixed diagnostic "+body.Length,async()=>{using var e=new YouTubeDesktopOAuth(new HttpClient(new OAuthReply(200,body)));var failure=await OAuthDenied(e);Check(failure.OAuth.Code==YouTubeOAuthCode.InvalidTokenResponse);});
await Test("refresh without returned scope keeps verified grant",async()=>{var json=JsonSerializer.Serialize(new{access_token="synthetic-access-private",token_type="Bearer",expires_in=3600});using var e=new YouTubeDesktopOAuth(new HttpClient(new OAuthReply(200,json)));var form=new Dictionary<string,string>{["client_id"]=Id,["grant_type"]="refresh_token",["refresh_token"]=PrivateMarker};var result=await e.ExchangeAsync(form,default,"synthetic-refresh-private");Check(result.Access.Valid&&result.RefreshToken=="synthetic-refresh-private");});
await Test("token network exception is sanitized",async()=>{var h=new OAuthReply(200,TokenJson()){Response=_=>Task.FromException<HttpResponseMessage>(new HttpRequestException(PrivateMarker))};using var e=new YouTubeDesktopOAuth(new HttpClient(h));var failure=await OAuthDenied(e);Check(failure.Reason==YouTubeFailure.NetworkInterrupted&&failure.OAuth.Code==YouTubeOAuthCode.NetworkFailure);});
await Test("token timeout is distinct from user cancellation",async()=>{var h=new OAuthReply(200,TokenJson()){Response=_=>Task.FromException<HttpResponseMessage>(new TaskCanceledException(PrivateMarker))};using var e=new YouTubeDesktopOAuth(new HttpClient(h));var failure=await OAuthDenied(e);Check(failure.OAuth.Code==YouTubeOAuthCode.TimedOut);});
await Test("caller cancellation remains cancellation",async()=>{using var c=new CancellationTokenSource();c.Cancel();using var e=new YouTubeDesktopOAuth(new HttpClient(new OAuthReply(200,TokenJson())));try{await e.ExchangeAsync(CodeForm(),c.Token);throw new Exception("Expected cancellation");}catch(OperationCanceledException){}});
await Test("missing refresh token reports validation before storage",async()=>{var store=new Store();using var a=Service(store,flow:new Flow{Pending=_=>Task.FromResult(new YouTubeOAuthTokens(Tokens().Access,""))});await a.BeginAsync();Check(a.State==YouTubeAuthState.AuthenticationError&&a.LastFailure.Code==YouTubeOAuthCode.MissingRefreshToken&&a.LastFailure.Stage==YouTubeOAuthStage.TokenValidation&&store.Saves==0);});
await Test("save failure reports ProtectedSave without leaking details",async()=>{var store=new Store{SaveFail=true};using var a=Service(store);await a.BeginAsync();Check(a.State==YouTubeAuthState.StorageError&&a.LastFailure.Stage==YouTubeOAuthStage.ProtectedSave&&a.LastFailure.Code==YouTubeOAuthCode.StorageFailure&&!a.Message.Contains("synthetic"));});
await Test("service displays Google error category and status safely",async()=>{var store=new Store();var log=new List<YouTubeOAuthDiagnostic>();var flow=new Flow{Pending=_=>Task.FromException<YouTubeOAuthTokens>(new YouTubeApiException(YouTubeFailure.AuthenticationExpired,new(YouTubeOAuthStage.TokenExchange,YouTubeOAuthCode.InvalidClient,401)))};using var a=new YouTubeAuthService(new(Id),store,flow,new Exchange(),log.Add);await a.BeginAsync();Check(a.State==YouTubeAuthState.AuthenticationError&&a.LastFailure.Code==YouTubeOAuthCode.InvalidClient&&a.Message.Contains("401")&&!a.Message.Contains(Id)&&log.Any(x=>x.Code==YouTubeOAuthCode.InvalidClient));});
await Test("diagnostic sink failure cannot prevent authentication",async()=>{using var a=new YouTubeAuthService(new(Id),new Store(),new Flow(),new Exchange(),_=>throw new Exception(PrivateMarker));await a.BeginAsync();Check(a.State==YouTubeAuthState.Linked);});
await Test("token diagnostic sink failure cannot affect valid response",async()=>{using var e=new YouTubeDesktopOAuth(new HttpClient(new OAuthReply(200,TokenJson())),_=>throw new Exception(PrivateMarker));Check((await e.ExchangeAsync(CodeForm(),default)).Access.Valid);});
await Test("state mismatch is distinct and never exposes state",()=>{var s=new YouTubePkceSession(Id,new Uri("http://127.0.0.1:12345/oauth2/callback"));try{s.Complete(new Uri(s.Redirect+"?state="+PrivateMarker+"&code="+PrivateMarker));throw new Exception("Expected state mismatch");}catch(YouTubeApiException error){Check(error.OAuth.Code==YouTubeOAuthCode.StateMismatch&&!error.OAuth.UserMessage.Contains(PrivateMarker));}return Task.CompletedTask;});
await Test("consent denial is distinct after state verification",()=>{var s=new YouTubePkceSession(Id,new Uri("http://127.0.0.1:12345/oauth2/callback"));var q=Query(s.AuthorizationUri);try{s.Complete(new Uri(s.Redirect+"?state="+q["state"]+"&error=access_denied"));throw new Exception("Expected denial");}catch(YouTubeApiException error){Check(error.OAuth.Code==YouTubeOAuthCode.AccessDenied);}return Task.CompletedTask;});
await Test("unknown enum and status cannot add arbitrary log values",()=>{var x=new YouTubeOAuthDiagnostic((YouTubeOAuthStage)123456,(YouTubeOAuthCode)123456,123456);Check(x.SafeLog=="YOUTUBE_OAUTH stage=Unknown code=UnexpectedFailure http=0");return Task.CompletedTask;});
await Test("refresh rejection retains normalized Google cause",async()=>{using var a=new YouTubeAuthService(new(Id),new Store{Data=Tokens(true)},new Flow(),new DiagnosticExchange());await Deny(YouTubeFailure.AuthenticationExpired,async()=>await a.GetAsync(default));Check(a.LastFailure.Code==YouTubeOAuthCode.InvalidRequest&&a.LastFailure.HttpStatus==400&&a.State==YouTubeAuthState.Expired&&!a.Message.Contains(Id));});
await Test("transient refresh failure preserves stored grant and cause",async()=>{var store=new Store{Data=Tokens(true)};using var a=Service(store,new Exchange{Failure=YouTubeFailure.NetworkInterrupted});await Deny(YouTubeFailure.NetworkInterrupted,async()=>await a.GetAsync(default));Check(store.Data!=null&&a.LastFailure.Code==YouTubeOAuthCode.NetworkFailure&&a.State==YouTubeAuthState.NetworkError);});
await Test("unlink cleanup failure does not display an obsolete Google cause",async()=>{var store=new Store{Data=Tokens(),DeleteFail=true};using var a=Service(store);await a.UnlinkAsync();Check(a.State==YouTubeAuthState.StorageError&&a.LastFailure.Code==YouTubeOAuthCode.StorageFailure&&a.LastFailure.Stage==YouTubeOAuthStage.ProtectedCleanup);});
await Test("accepted callback can still fail during token exchange",async()=>{var exchange=new DiagnosticExchange();Task browser=null;string reply="";var flow=new YouTubeLoopbackOAuth(exchange,uri=>{var q=Query(uri);var redirect=new Uri(q["redirect_uri"]);browser=Task.Run(async()=>reply=await Callback(redirect,"code=synthetic-code&state="+q["state"]));});using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(5));try{await flow.AuthorizeAsync(new(Id),timeout.Token);throw new Exception("Expected token rejection");}catch(YouTubeApiException error){Check(error.OAuth.Stage==YouTubeOAuthStage.TokenExchange&&error.OAuth.Code==YouTubeOAuthCode.InvalidRequest);}await browser;Check(reply.StartsWith("HTTP/1.1 200")&&exchange.Calls==1&&!reply.Contains("synthetic"));});
}
sealed class DiagnosticExchange:IYouTubeTokenExchange {internal int Calls;public Task<YouTubeOAuthTokens> ExchangeAsync(Dictionary<string,string> f,CancellationToken t,string p=null){Calls++;throw new YouTubeApiException(YouTubeFailure.AuthenticationExpired,new(YouTubeOAuthStage.TokenExchange,YouTubeOAuthCode.InvalidRequest,400));}public Task RevokeAsync(string v,CancellationToken t)=>Task.CompletedTask;public void Dispose(){}}
}
